/* Canonical PC File_header must not enter the legacy G1 container path. */
#include "dm2_v1_dungeon_loader.h"
#include <stdio.h>
#include <stdlib.h>
static unsigned char *read_file(const char *p,int *s){FILE*f=fopen(p,"rb");long n;unsigned char*b;*s=0;if(!f||fseek(f,0,SEEK_END)||(n=ftell(f))!=39437L||fseek(f,0,SEEK_SET)){if(f)fclose(f);return NULL;}b=malloc((size_t)n);if(!b||fread(b,1,(size_t)n,f)!=(size_t)n){free(b);fclose(f);return NULL;}fclose(f);*s=(int)n;return b;}
int main(int argc,char **argv){const char*p=argc>=2?argv[1]:NULL;int s;unsigned char*b;DM2_V1_DungeonData d;DM2_V1_G1RuntimeMapContainerReceipt r;if(!p){puts("SKIP: no local canonical DM2 data");return 0;}b=read_file(p,&s);if(!b||b[0]||b[1]||b[2]!=0x47||b[3]!=0x31||b[4]!=44||b[5]||b[6]!=28||b[7]||dm2_v1_dungeon_load(&d,b,s)){free(b);fputs("FAIL: canonical File_header input was not accepted\n",stderr);return 1;}free(b);r.committed=-1;if(dm2_v1_dungeon_materialize_g1_runtime_map_containers(&d,0,&r)||r.committed!=-1){dm2_v1_dungeon_free(&d);fputs("FAIL: File_header entered legacy G1 container path\n",stderr);return 1;}dm2_v1_dungeon_free(&d);puts("PASS: File_header leaves legacy G1 container path unavailable");return 0;}
